<?php session_start(); require 'config/database.php'; require 'lib_security.php'; if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete'])){verifyCsrf();$id=(int)$_POST['delete'];$pdo->prepare('DELETE FROM programs WHERE id=?')->execute([$id]);header('Location: programs.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf(); $id=(int)($_POST['id']??0);$level=$_POST['level'];$name=trim($_POST['name']);$spec=trim($_POST['specialization']??'')?:null;if($id)$pdo->prepare('UPDATE programs SET level=?,name=?,specialization=? WHERE id=?')->execute([$level,$name,$spec,$id]);else$pdo->prepare('INSERT INTO programs(level,name,specialization) VALUES(?,?,?)')->execute([$level,$name,$spec]);header('Location: programs.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM programs WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM programs ORDER BY FIELD(level,"HSSC","BS","ADP"),name')->fetchAll();$pageTitle='Programs';require'includes/header.php';?>
<div class="container py-4"><div class="d-flex justify-content-between"><h2>Programs</h2><a href="admin.php" class="btn btn-outline-secondary">Dashboard</a></div><div class="card shadow-sm my-3"><div class="card-body"><form method="post" class="row g-2"><?php echo csrfField(); ?><input type="hidden" name="id" value="<?=htmlspecialchars($edit['id']??'')?>"><div class="col-md-2"><select name="level" class="form-select"><option <?=($edit['level']??'')==='HSSC'?'selected':''?>>HSSC</option><option <?=($edit['level']??'')==='BS'?'selected':''?>>BS</option><option <?=($edit['level']??'')==='ADP'?'selected':''?>>ADP</option></select></div><div class="col-md-3"><input name="name" class="form-control" placeholder="Program name" required value="<?=htmlspecialchars($edit['name']??'')?>"></div><div class="col-md-4"><input name="specialization" class="form-control" placeholder="Specialization (optional)" value="<?=htmlspecialchars($edit['specialization']??'')?>"></div><div class="col-md-3"><button class="btn btn-primary">Save Program</button> <?php if($edit):?><a href="programs.php" class="btn btn-light">Cancel</a><?php endif;?></div></form></div></div>
<div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Level</th><th>Program</th><th>Specialization</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['level']?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['specialization']??'—')?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete this program? Subjects using it will also be removed.')">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require'includes/footer.php';?>
